solution:
export type First<T extends any[]> = T extends [infer F, ...any[]] ? F : never;
export type Last<T extends any[]> = T extends [...any[], infer L] ? L : never;
export type Tail<T extends any[]> = T extends [any, ...infer R] ? R : never;
